import { storyKey } from '../card';
import { MIN_SCORE, SOURCE, STORIES } from '../stories';

// stories.ts is generated by tools/build-horror.mjs from a scrape that is not
// in this repo, so nothing else can catch it going wrong. These are the
// invariants the deck, the list and the card all assume.
describe('the stories', () => {
  it('holds the corpus the generator kept', () => {
    expect(STORIES).toHaveLength(6861);
  });

  it('carries no empty or untrimmed sentence', () => {
    for (const s of STORIES) {
      expect(s.setup.trim()).toBe(s.setup);
      expect(s.turn.trim()).toBe(s.turn);
      expect(s.setup.length).toBeGreaterThan(0);
      expect(s.turn.length).toBeGreaterThan(0);
    }
  });

  it('carries no duplicate', () => {
    expect(new Set(STORIES.map(storyKey)).size).toBe(STORIES.length);
  });

  it('clears the floor it was generated at', () => {
    expect(MIN_SCORE).toBe(1000);
    for (const s of STORIES) expect(s.score).toBeGreaterThanOrEqual(MIN_SCORE);
  });

  // The one invariant that makes regeneration safe. Score-descending means a
  // lower --min-score only ever APPENDS: every story already here keeps its
  // position, so the numeral on a row stays put and a favorite keyed by text
  // still finds the same card.
  it('runs score-descending, so taking more only appends', () => {
    for (let i = 1; i < STORIES.length; i++) {
      expect(STORIES[i].score).toBeLessThanOrEqual(STORIES[i - 1].score);
    }
  });

  it('names the community it came from, since no story carries an author', () => {
    expect(SOURCE.community).toBe('r/TwoSentenceHorror');
    for (const s of STORIES) {
      expect(s).not.toHaveProperty('author');
    }
  });
});
